"""Standard and Rational Bloom filters.

R1: all-zero bit array of length m; insertion sets k indices to 1; query
returns absent if any index is 0.
R4/R5/R6 (Rational BF): floor(k) always-applied hashes plus one extra hash
H_{floor(k)+1} applied iff H_r(x) < (k - floor(k)) * m, with the same
deterministic rule at insertion and query time (no false negatives).
"""

from __future__ import annotations

import hash_utils


class _BitArray:
    """One bit per index in a bytearray (R1)."""

    def __init__(self, m: int):
        self.m = m
        self._bytes = bytearray((m + 7) // 8)

    def set(self, idx: int) -> None:
        self._bytes[idx >> 3] |= 1 << (idx & 7)

    def get(self, idx: int) -> bool:
        return (self._bytes[idx >> 3] >> (idx & 7)) & 1 == 1

    def fraction_of_zeros(self) -> float:
        ones = sum(bin(b).count("1") for b in self._bytes)
        # Mask off padding bits if m is not a multiple of 8.
        if self.m % 8:
            padding = 8 - (self.m % 8)
            last = self._bytes[-1] >> (8 - padding)
            ones -= bin(last).count("1")
        return 1.0 - ones / self.m


class StandardBloomFilter:
    """Standard BF with integer k double-hashed indices (baseline, R10)."""

    def __init__(self, m: int, k: int):
        if k < 0 or int(k) != k:
            raise ValueError("standard BF needs a non-negative integer k")
        self.m = m
        self.k = int(k)
        self.bits = _BitArray(m)

    def _indices(self, x: int):
        h1, h2 = hash_utils.hash_pair(x)
        return [hash_utils.index_from_pair(h1, h2, i, self.m) for i in range(self.k)]

    def insert(self, x: int) -> None:
        for idx in self._indices(x):
            self.bits.set(idx)

    def query(self, x: int) -> bool:
        return all(self.bits.get(idx) for idx in self._indices(x))

    def fraction_of_zeros(self) -> float:
        return self.bits.fraction_of_zeros()


class RationalBloomFilter:
    """Rational BF with a real-valued number k of hash functions."""

    def __init__(self, m: int, k: float):
        if k < 0:
            raise ValueError("k must be non-negative")
        self.m = m
        self.k = float(k)
        self.floor_k = int(self.k // 1)
        self.frac = self.k - self.floor_k
        self.bits = _BitArray(m)

    def _application(self, x: int):
        return hash_utils.rational_application(x, self.m, self.k)

    def insert(self, x: int) -> None:
        base, extra, activated, _ = self._application(x)
        for idx in base:
            self.bits.set(idx)
        if activated and extra is not None:
            self.bits.set(extra)

    def query(self, x: int) -> bool:
        base, extra, activated, _ = self._application(x)
        for idx in base:
            if not self.bits.get(idx):
                return False
        if activated and extra is not None and not self.bits.get(extra):
            return False
        return True

    def fraction_of_zeros(self) -> float:
        return self.bits.fraction_of_zeros()

